/* Shared data/status helpers and UI behavior layered over the retained Worker app. */
/**
 * @typedef {'ok'|'warning'|'critical'|'loading'|'empty'|'stale'|'offline'|'partial'|'error'} DashboardDataStatus
 * @template T
 * @typedef {Object} DashboardMetric
 * @property {T|null} value — measured value; null means that no value was supplied.
 * @property {DashboardDataStatus} status — freshness/quality state, not a substitute for value.
 * @property {string|null} measuredAt — timestamp of the measurement when known.
 * @property {string|null} source — source endpoint or device identifier when known.
 * @property {string|null} quality — backend-provided quality information when known.
 * @property {number|null} lastSuccessfulUpdate — epoch milliseconds of the last successful request.
 */
const hmToken=name=>getComputedStyle(document.documentElement).getPropertyValue(name).trim();
const HM_STATUS_LABELS={ok:'Актуально',warning:'Попередження',critical:'Критично',loading:'Завантаження',empty:'Немає даних',stale:'Застаріло',offline:'Офлайн',partial:'Неповні дані',error:'Помилка'};
