state.fullscreenRestore ||= null;
state.energyMode ||= 'energy';if(state.chartMetrics?.voltage==='energyCost')state.chartMetrics.voltage='energy';
state.climateRoomFocus ||= null;
const hmNumber=v=>v===null||v===undefined||(typeof v==='string'&&v.trim()==='')||!Number.isFinite(Number(v))?null:Number(v);
const hmMetric=(value,extra={})=>{const n=hmNumber(value);return {value:n,status:extra.status||(n===null?'empty':'ok'),measuredAt:extra.measuredAt??null,source:extra.source??null,quality:extra.quality??null,lastSuccessfulUpdate:extra.lastSuccessfulUpdate??null}};
const hmVal=(value,unit='',digits=1)=>{const n=hmNumber(value);return n===null?'—':fmt(n,digits)+(unit?' '+unit:'')};
const hmWhen=v=>{if(!v)return 'час не вказано';const d=new Date(String(v).includes('T')?v:String(v).replace(' ','T')+'Z');return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat('uk-UA',{timeZone:hmTimeZone(),day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(d)};
function hmTimeZone(){return state.dash?.weather?.timezone||state.dash?.location?.timezone||state.dash?.settings?.timezone||state.overview?.settings?.timezone||'Europe/Kyiv'}
function hmStatusFor(metric){if(!metric)return 'empty';if(metric.status)return metric.status;if(metric.online===false||metric.status==='offline')return 'offline';if(metric.age_minutes!=null&&metric.age_minutes>(Number(state.dash?.settings?.device_timeout_minutes)||15))return 'stale';return metric.value===null||metric.value===undefined?'empty':'ok'}
function hmBadge(status,label){const s=HM_STATUS_LABELS[status]||status||'Невідомо';return `<span class="stateText ${esc(status||'empty')}">${esc(label||s)}</span>`}
function hmFreshness(record){if(!record)return 'Час оновлення невідомий';const age=hmNumber(record.age_minutes);if(age!==null)return ageText(age);if(record.measured_at||record.measuredAt||record.last_seen)return 'Останні дані: '+hmWhen(record.measured_at||record.measuredAt||record.last_seen);return 'Час оновлення невідомий'}
function hmLink(path,label,extra=''){return `<button class="eventAction" type="button" data-deep-link="${esc(path)}" ${extra}>${esc(label||'Відкрити')}</button>`}
function hmPageTitle(view){return ({home:'Головна · Стан дому',climate:'Клімат · Огляд',energy:'Енергія · Огляд',weather:'Погода · Прогноз',devices:'Пристрої · Стан і зв’язок',timeline:'Події · Історія',admin:'Керування · Налаштування'})[view]||'Home Monitor'}
function showView(view,options={}){const valid=['home','climate','energy','weather','devices','timeline','admin'];if(!valid.includes(view))view='home';document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===view));document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.view===view));state.loadedTabs.add(view);setText('pageSubtitle',hmPageTitle(view));if(view==='timeline')loadTimeline();if(view==='admin'&&state.token)loadAdmin();if(view==='weather')renderWeather48();if(view==='devices')renderDevicesPage();if(view==='climate'){renderClimateSummary();renderFloorPlan();renderCharts()}if(view==='energy'){renderEnergyExtras();renderEnergyPage();renderChartsEnergy()}requestAnimationFrame(()=>Object.values(state.charts).forEach(c=>c?.resize?.()));}
function hmNavigate(path){const u=new URL(path,location.origin),view=u.pathname.split('/').filter(Boolean)[0]||'home',page=view;const valid=['home','climate','energy','weather','devices','timeline','admin'];const mapped=valid.includes(page)?page:'home';if(mapped==='devices'){state.selectedDeviceId=u.pathname.split('/').filter(Boolean)[1]||null;state.deviceFilter=u.searchParams.get('status')==='attention'?'attention':'all'}if(location.pathname==='/'||location.pathname==='/index.html')history.replaceState({...history.state,hmHome:true},'',location.pathname+location.search);const previousScroll=window.scrollY;history.replaceState({...history.state,hmScrollY:previousScroll,hmPath:location.pathname+location.search},'',location.pathname+location.search);history.pushState({hmView:mapped,hmScrollY:0,hmPath:u.pathname+u.search},'',u.pathname+u.search);sessionStorage.setItem('hmDashboardScroll',String(previousScroll));showView(mapped);if(mapped==='climate'){const id=u.searchParams.get('room');if(id){const room=HM_ROOMS.find(x=>x.id===id||x.legacy===id);if(room)selectPlanRoom(room.legacy)}}if(mapped==='energy'){const metric=u.searchParams.get('metric');if(metric&&['power','energy','cost','voltage'].includes(metric)){state.chartMetrics.voltage=metric;state.energyMode=metric;document.querySelectorAll('.energyMetricSwitch [data-metric]').forEach(b=>b.classList.toggle('active',b.dataset.metric===metric))}const period=u.searchParams.get('period');if(period&&['day','week','month','custom'].includes(period)){state.smartPeriods.energy2=period;document.querySelectorAll('.smartPeriod[data-smart-scope="energy2"] [data-p]').forEach(b=>b.classList.toggle('active',b.dataset.p===period));loadSmartRange('energy2',period).catch(error=>console.error('Unable to load deep-linked energy period',error))}else renderChartsEnergy()}if(mapped==='weather'){state.weatherDeepLinkTimestamp=u.searchParams.get('timestamp')||null;state.weatherMetric='temperature';renderWeather48()}window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
document.addEventListener('keydown',e=>{const card=e.target.closest('[role="button"][data-deep-link]');if(card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();hmNavigate(card.dataset.deepLink)}});
document.addEventListener('click',e=>{const link=e.target.closest('[data-deep-link]');if(link){e.preventDefault();hmNavigate(link.dataset.deepLink);return}const nav=e.target.closest('[data-go]');if(nav){e.preventDefault();hmNavigate('/'+nav.dataset.go);return}if(e.target.closest('#scoreDetails'))showDetail('Як формується оцінка',`<p>Оцінка та її фактори відображаються лише на основі відповіді backend. Ваги або прогноз оцінки на клієнті не розраховуються.</p><p>Доступні фактори: клімат, енергія, погода, пристрої та активні події.</p>`);});
