 const events=hmDedupeEvents(alerts,[],devices),eventRoot=$('homeEvents');if(eventRoot){if(!events.length)eventRoot.innerHTML='<div class="emptyState">Активних подій не виявлено за доступними даними.</div>';else eventRoot.innerHTML=events.slice(0,2).map(e=>`<div class="eventRow"><span class="eventSeverity ${esc(e.severity)}" aria-hidden="true"></span><div><strong>${esc(e.title)}</strong><p>${esc(e.message||'Додаткових деталей немає.')}</p><span class="stateText ${e.severity==='critical'?'critical':e.severity==='warning'?'warning':'info'}">${esc(e.severity==='critical'?'Критично':e.severity==='warning'?'Попередження':'Інформація')} · ${esc(e.source)}</span></div><div><time>${esc(e.timestamp?hmWhen(e.timestamp):'')}</time><br>${hmLink(e.deepLink,'Перевірити')}</div></div>`).join('')+(events.length>2?`<div class="muted">Ще ${events.length-2} події — у журналі.</div>`:'')}
 const climateDevices=devices.filter(x=>x.device_type==='climate'),indoor=climateDevices.filter(x=>!x.is_outdoor),online=devices.filter(x=>x.online===true||['online','ok'].includes(String(x.status||'').toLowerCase())).length,outdoor=climateDevices.find(x=>x.is_outdoor),roomTemp=indoor.map(x=>hmNumber(x.temperature)).filter(x=>x!==null),roomHum=indoor.map(x=>hmNumber(x.humidity)).filter(x=>x!==null),avgTemp=roomTemp.length?roomTemp.reduce((a,b)=>a+b,0)/roomTemp.length:null,avgHum=roomHum.length?roomHum.reduce((a,b)=>a+b,0)/roomHum.length:null;
 const snapshots=[{title:'Клімат дому',icon:'🌡',value:avgTemp===null?'—':hmVal(avgTemp,'°C',1),secondary:avgHum===null?'Вологість: —':`Середня вологість ${hmVal(avgHum,'%',0)}`,status:state.widgetStatus.climate|| (climateDevices.some(x=>x.online===false)?'stale':'ok'),foot:climateDevices.length?`${climateDevices.filter(x=>x.online===true||x.status==='online'||x.status==='ok').length}/${climateDevices.length} датчиків на зв’язку`:'Датчики ще не передали дані',path:'/climate'}, {title:'Енергія дому',icon:'⚡',value:hmNumber(power.power)===null?'—':hmVal(power.power,'Вт',0),secondary:hmNumber(today.energy_total??today.energy_kwh)===null?'Споживання сьогодні: —':`Сьогодні ${hmVal(today.energy_total??today.energy_kwh,'кВт·год',2)}`,status:state.widgetStatus.energy||'ok',foot:hmNumber(today.cost_total??today.cost)===null?'Вартість: немає даних':`Витрати ${hmVal(today.cost_total??today.cost,'грн',2)}`,path:'/energy?metric=power&period=day'}, {title:'Погода',icon:current.weather_icon||'🌦',value:hmNumber(current.temperature)===null?'—':hmVal(current.temperature,'°C',1),secondary:current.feels_like==null?'Відчувається як: —':`Відчувається як ${hmVal(current.feels_like,'°C',1)}`,status:state.widgetStatus.weather||'ok',foot:current.weather_description||'Опис погоди не переданий API',path:'/weather?horizon=48h'}];setHTML('homeSnapshots',snapshots.map(x=>`<article class="snapshotCard glass" role="button" tabindex="0" data-deep-link="${x.path}" aria-label="Відкрити ${x.title}"><div class="snapshotCardHead"><span>${x.icon} ${esc(x.title)}</span>${hmBadge(x.status)}</div><div class="snapshotPrimary">${esc(x.value)}</div><div class="snapshotSecondary">${esc(x.secondary)}</div><div class="snapshotFoot"><span>${esc(x.foot)}</span><span class="snapshotArrow">Детальніше ↗</span></div></article>`).join(''));
 const daily=(weather.daily||d?.weather?.daily||[]).slice(0,7),nums=daily.flatMap(x=>[hmNumber(x.temp_min),hmNumber(x.temp_max)]).filter(x=>x!==null),minAll=nums.length?Math.min(...nums):null,maxAll=nums.length?Math.max(...nums):null;setHTML('homeForecast',daily.length?daily.map((x,i)=>{const lo=hmNumber(x.temp_min),hi=hmNumber(x.temp_max),left=minAll===null||lo===null?0:(lo-minAll)/Math.max(1,maxAll-minAll)*100,width=lo===null||hi===null?0:(hi-lo)/Math.max(1,maxAll-minAll)*100;return `<button class="homeForecastDay" type="button" data-deep-link="/weather?horizon=48h&timestamp=${encodeURIComponent(x.date||x.forecast_date||'')}"><strong>${esc(x.day_label||hmWhen(x.date||x.forecast_time).split(',')[0]||`День ${i+1}`)}</strong><div class="forecastIcon">${esc(x.weather_icon||'🌦')}</div><div>${hmVal(lo,'°',0)} / ${hmVal(hi,'°',0)}</div><div class="forecastRange"><span style="left:${left}%;width:${Math.max(0,Math.min(100,width))}%"></span></div><small>Опади ${hmVal(x.precipitation_probability,'%',0)}<br>Вітер ${hmVal(x.wind_speed,'км/год',0)}</small></button>`}).join(''):'<div class="emptyState">API не повернув семиденний прогноз. Немає демонстраційних значень.</div>');
 setHTML('homeDeviceCounts',`<div class="countCard"><b>${state.deviceStatus?.online==null?'—':fmt(state.deviceStatus.online,0)}</b><span>Онлайн</span></div><div class="countCard"><b>${Array.isArray(state.deviceStatus?.items)?devices.filter(x=>x.status==='warning'||x.status==='offline'||x.online===false).length:'—'}</b><span>Потребують перевірки</span></div><div class="countCard"><b>${Array.isArray(state.deviceStatus?.items)?devices.filter(x=>x.battery_low===true||x.low_battery===true||x.battery_status==='low').length:'—'}</b><span>Низький заряд</span></div>`);const attentionDevices=devices.filter(x=>x.online===false||x.status==='offline'||x.status==='warning'||x.battery_low===true||x.low_battery===true).slice(0,3);setHTML('homeDeviceAttention',attentionDevices.length?attentionDevices.map(x=>`<div class="deviceAttentionRow"><strong>${esc(x.device_name||'Пристрій')}</strong><p class="muted">${esc(x.status==='offline'||x.online===false?'Немає зв’язку':x.status==='warning'?'Затримка даних': 'Потрібна перевірка заряду')} · ${esc(ageText(hmNumber(x.age_minutes)))}</p>${hmLink(x.device_id?`/devices/${encodeURIComponent(x.device_id)}`:'/devices?status=attention','Перевірити')}</div>`).join(''):'<div class="emptyState">Немає відомих проблемних пристроїв або статус пристроїв ще не отримано.</div>');
