function hmChartRange(key,total){const v=state.chartViewport[key]||{zoom:1,offset:0},count=Math.max(6,Math.ceil(total/Math.max(1,v.zoom))),maxOffset=Math.max(0,total-count),offset=Math.min(maxOffset,Math.max(0,v.offset));return {start:Math.max(0,total-count-offset),end:total-offset,count,offset,maxOffset}}
function hmSlice(key,labels,datasets){const r=hmChartRange(key,labels.length);return {labels:labels.slice(r.start,r.end),datasets:datasets.map(d=>({...d,data:(d.data||[]).slice(r.start,r.end)})),range:r}}
