/* Persist only the stable user preferences requested by the specification. Fullscreen and zoom are transient. */
const HM_PREF_KEY='hmDashboardPreferences';
function hmSavePreferences(){try{localStorage.setItem(HM_PREF_KEY,JSON.stringify({climateMode:state.chartMetrics.climate,planMetric:state.floorPlanMetric,selectedRooms:Array.isArray(state.climateSelectedRooms)?state.climateSelectedRooms:[],roomFocus:state.climateRoomFocus||null,periods:{climate:state.smartPeriods.climate||'day',energy2:state.smartPeriods.energy2||'day'},customRanges:Object.fromEntries(['climate','energy2'].map(scope=>{const c=document.querySelector(`[data-custom="${scope}"]`);return [scope,{from:c?.querySelector('.from')?.value||'',to:c?.querySelector('.to')?.value||''}]}))}))}catch(error){console.warn('Home Monitor: preferences could not be saved',error)}}
