/* Keep period controls on the new chart pipeline; do not let legacy chart renderers overwrite the redesigned canvases. */
async function loadSmartRange(scope,period,from=null,to=null){
 const isClimate=scope==='climate',target=isClimate?'climate':'energy';
 state.smartControllers=state.smartControllers||{};state.smartControllers[scope]?.abort();
 const controller=new AbortController();state.smartControllers[scope]=controller;
 try{
  let endpoint,data;
  if(isClimate){const days=period==='day'?1:period==='week'?7:period==='year'?365:period==='custom'&&from&&to?Math.max(1,Math.ceil((Date.parse(to+'T00:00:00Z')-Date.parse(from+'T00:00:00Z'))/86400000)+1):31;const hours=Math.min(744,Math.max(24,days*24));endpoint='/charts/climate?hours='+hours;data=await req(endpoint,{ttl:0,signal:controller.signal});}
  else if(scope==='energy2'&&state.chartMetrics.voltage==='power'){const days=period==='day'?1:period==='week'?7:period==='month'?30:period==='custom'&&from&&to?Math.max(1,Math.ceil((Date.parse(to+'T00:00:00Z')-Date.parse(from+'T00:00:00Z'))/86400000)+1):1;const hours=Math.min(720,Math.max(1,days*24));endpoint='/charts/power?hours='+hours;data=await req(endpoint,{ttl:0,signal:controller.signal});}
  else{const params=new URLSearchParams({period});if(from)params.set('from',from);if(to)params.set('to',to);endpoint='/charts/energy/range?'+params.toString();data=await req(endpoint,{ttl:0,signal:controller.signal});}
  if(state.smartControllers[scope]!==controller||controller.signal.aborted)return null;
  if(isClimate){state.climate=data;state.smartPeriods.climate=period;state.widgetStatus.climate='ok';state.freshness.climate={lastSuccessfulUpdate:Date.now(),source:endpoint};renderClimateSummary();renderFloorPlan();renderCharts();}
  else{if(scope==='energy2'&&state.chartMetrics.voltage==='power')state.power=data;state.rangeSeries[scope]=data;state.smartPeriods[scope]=period;state.widgetStatus.energy='ok';state.freshness.energy={lastSuccessfulUpdate:Date.now(),source:endpoint};renderEnergyExtras();renderEnergyPage();renderChartsEnergy();}
  return data;
 }catch(error){if(controller.signal.aborted||error?.name==='AbortError')return null;state.widgetStatus[target]=target==='climate'?(state.climate?'stale':'error'):(state.rangeSeries[scope]||state.energySeries?'stale':'error');console.error('Home Monitor: '+scope+' period load failed',error);toast('Не вдалося оновити період: '+(error?.message||'помилка джерела'));if(isClimate)renderClimateSummary();else renderEnergyPage();return null;}
 finally{if(state.smartControllers[scope]===controller)delete state.smartControllers[scope];}
}
