function closeFullscreenTarget(){const restore=state.fullscreenRestore;if(!restore)return false;const {content,parent,next,focus,scrollY}=restore;if(parent){if(next&&next.parentNode===parent)parent.insertBefore(content,next);else parent.appendChild(content)}state.fullscreenRestore=null;$('detailModal')?.classList.remove('show','modalChart');document.body.classList.remove('modalOpen');requestAnimationFrame(()=>{Object.values(state.charts).forEach(c=>c?.resize?.());if(focus&&typeof focus.focus==='function')focus.focus();window.scrollTo({top:scrollY,behavior:'auto'})});return true}
const originalCloseDetail=$('detailClose')?.onclick;$('detailClose')?.addEventListener('click',()=>closeFullscreenTarget());$('detailModal')?.addEventListener('click',e=>{if(e.target===$('detailModal'))closeFullscreenTarget()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.fullscreenRestore)closeFullscreenTarget()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-chart-action]');if(!b)return;const action=b.dataset.chartAction,target=b.dataset.chartTarget||'energy';if(action==='fullscreen'){openFullscreenTarget(target);return}if(action==='expand'){const el=target==='climate'?$('climateTempContainer')?.closest('.climateChartPanel'):target==='energy' ?$('energyChartContainer'):target==='weather'?$('weatherChartContainer'):$(target+'Container');if(el){el.classList.toggle('is-expanded');b.textContent=el.classList.contains('is-expanded')?'Зменшити':'Збільшити';requestAnimationFrame(()=>Object.values(state.charts).forEach(c=>c?.resize?.()))}return}const key=target.startsWith('climate')?'climate':target;state.chartViewport[key]||={zoom:1,offset:0};const v=state.chartViewport[key];if(action==='zoom-in')v.zoom=Math.min(12,v.zoom*1.5);else if(action==='zoom-out')v.zoom=Math.max(1,v.zoom/1.5);else if(action==='reset'){v.zoom=1;v.offset=0}else if(action==='pan-left')v.offset+=Math.max(2,Math.round(20/v.zoom));else if(action==='pan-right')v.offset=Math.max(0,v.offset-Math.max(2,Math.round(20/v.zoom)));if(key==='climate')renderCharts();else if(key==='energy'){renderChartsEnergy()}else if(key==='weather')renderWeather48()});
document.querySelectorAll('[data-chart-navigator]').forEach(input=>input.addEventListener('input',()=>{const key=input.dataset.chartNavigator,v=state.chartViewport[key]||{zoom:1,offset:0};const dataLength=key==='climate'?Math.max(0,...hmSeriesEntries().map(x=>(x.series.labels||[]).length)):key==='weather'?(state.dash?.weather?.hourly_3h||state.dash?.weather?.hourly||[]).length:(state.rangeSeries.energy2?.points||state.rangeSeries.energy?.points||state.energySeries?.points||state.power?.labels||[]).length;const visible=Math.max(6,Math.ceil(dataLength/Math.max(1,v.zoom))),max=Math.max(0,dataLength-visible);v.offset=Math.round(max*(1-Number(input.value)/100));state.chartViewport[key]=v;if(key==='climate')renderCharts();else if(key==='energy')renderChartsEnergy();else if(key==='weather')renderWeather48()}));
$('quickRefresh')?.addEventListener('click',()=>loadAll(true));$('heroRefresh')?.addEventListener('click',()=>loadAll(true));$('retryEnergy')?.addEventListener('click',()=>loadAll(true));
/* Every domain loads independently. A failed refresh keeps last-known-good data. */
async function loadAll(force=false){if(state.loading||(!force&&document.visibilityState!=='visible'))return;state.loading=true;document.body.classList.add('isLoading');const required=[['overview','/control/overview',v=>state.overview=v,60000],['dashboard','/dashboard',v=>state.dash=v,60000],['score','/home-score',v=>state.score=v,300000],['devices','/devices/status',v=>state.deviceStatus=v,60000]];const wantCharts=state.loadedTabs.has('home')||state.loadedTabs.has('energy')||state.loadedTabs.has('climate');const extra=wantCharts?[['power','/charts/power?hours='+(state.chartHours.power||168),v=>state.power=v,300000],['climateHistory','/charts/climate?hours='+(state.chartHours.climate||168),v=>state.climate=v,300000],['energyHistory','/charts/energy?hours='+(state.chartHours.energy||168),v=>state.energySeries=v,300000],['homeEnergy','/charts/energy/range?period=day',v=>state.homeEnergy24=v,60000]]:[];const tasks=[...required,...extra].map(async([key,path,apply,ttl])=>{try{const data=await req(path,{ttl:force?0:ttl});apply(data);state.widgetStatus[key==='climateHistory'?'climate':key==='energyHistory'?'energy':key==='homeEnergy'?'energy':key==='dashboard'?'weather':key]= 'ok';state.freshness[key]={lastSuccessfulUpdate:Date.now(),source:path};return {key,status:'ok'}}catch(error){const widgetKey=key==='climateHistory'?'climate':key==='energyHistory'?'energy':key==='homeEnergy'?'energy':key==='dashboard'?'weather':key;const hadGood=key==='overview'?!!state.overview:key==='dashboard'?!!state.dash:key==='score'?!!state.score:key==='devices'?!!state.deviceStatus:key==='power'?!!state.power:key==='climateHistory'?!!state.climate:key==='energyHistory'?!!state.energySeries:key==='homeEnergy'?!!state.homeEnergy24:false;state.widgetStatus[widgetKey]=hadGood?'stale':'error';state.freshness[key]||={lastSuccessfulUpdate:null,source:path};console.error(`Home Monitor: ${key} request failed`,error);return {key,status:'error',error}}});try{const results=await Promise.all(tasks);if(!state.rangeSeries.energy)loadSmartRange('energy',state.smartPeriods.energy||'day').catch(e=>console.error('Energy range loading failed',e));if(!state.rangeSeries.energy2)loadSmartRange('energy2',state.smartPeriods.energy2||'day').catch(e=>console.error('Energy comparison range loading failed',e));if(!state.tariffRange)loadTariffRange().catch(e=>console.error('Tariff range loading failed',e));if(!state.loadedClimateDefault){state.loadedClimateDefault=true;loadSmartRange('climate',state.smartPeriods.climate||'day').catch(e=>console.error('Climate history loading failed',e))}render();const failures=results.filter(x=>x.status==='error').length;if(failures){setText('updated',`Частково оновлено · помилок джерел: ${failures}`);setText('homeUpdated',$('updated')?.textContent||'')}else{setText('updated','Оновлено '+new Date().toLocaleTimeString('uk-UA',{hour:'2-digit',minute:'2-digit'}));setText('homeUpdated',$('updated').textContent)}return results}finally{state.loading=false;document.body.classList.remove('isLoading')}}
/* Add deep-link support for direct navigation and restore the previous overview scroll position. */
function applyInitialRoute(){const path=location.pathname.split('/').filter(Boolean)[0]||'home',view=['home','climate','energy','weather','devices','timeline','admin'].includes(path)?path:'home';if(view==='devices'){state.selectedDeviceId=location.pathname.split('/').filter(Boolean)[1]||null;state.deviceFilter=new URLSearchParams(location.search).get('status')==='attention'?'attention':'all'}const params=new URLSearchParams(location.search);if(view==='energy'){const metric=params.get('metric'),period=params.get('period');if(metric&&['power','energy','cost','voltage'].includes(metric)){state.chartMetrics.voltage=metric;state.energyMode=metric}if(period&&['day','week','month','custom'].includes(period))state.smartPeriods.energy2=period}showView(view,{initial:true});if(view==='climate'&&params.get('room')){const r=HM_ROOMS.find(x=>x.id===params.get('room')||x.legacy===params.get('room'));if(r)selectPlanRoom(r.legacy)}if(view==='weather')state.weatherDeepLinkTimestamp=params.get('timestamp');if(view==='energy'&&params.get('period'))document.querySelectorAll('.smartPeriod[data-smart-scope="energy2"] [data-p]').forEach(b=>b.classList.toggle('active',b.dataset.p===params.get('period')));}
document.querySelectorAll('[data-device-filter]').forEach(b=>b.addEventListener('click',()=>{state.deviceFilter=b.dataset.deviceFilter;state.selectedDeviceId=null;history.pushState({hmView:'devices'},'',state.deviceFilter==='all'?'/devices':`/devices?status=${encodeURIComponent(state.deviceFilter)}`);renderDevicesPage()}));document.addEventListener('click',e=>{const b=e.target.closest('[data-device-open]');if(b){hmNavigate('/devices/'+encodeURIComponent(b.dataset.deviceOpen));return}const p=e.target.closest('[data-plan-action]');if(p){const action=p.dataset.planAction;if(action==='fit'){state.floorPlanZoom=1;state.floorPlanPan={x:0,y:0}}else if(action==='zoom-in')state.floorPlanZoom=Math.min(2.5,(state.floorPlanZoom||1)*1.2);else if(action==='zoom-out')state.floorPlanZoom=Math.max(.8,(state.floorPlanZoom||1)/1.2);else if(action==='pan-left')state.floorPlanPan.x-=45;else if(action==='pan-right')state.floorPlanPan.x+=45;else if(action==='pan-up')state.floorPlanPan.y-=35;else if(action==='pan-down')state.floorPlanPan.y+=35;renderFloorPlan()}});$('devicesRefresh')?.addEventListener('click',()=>loadAll(true));const floorSvg=$('floorPlanSvg');const planPointers=new Map();let planGesture=null,planDragClick=false;const planDistance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);floorSvg?.addEventListener('pointerdown',e=>{planPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const pts=[...planPointers.values()];if(pts.length===1)planGesture={type:'pan',id:e.pointerId,startX:e.clientX,startY:e.clientY,startPan:{...state.floorPlanPan},moved:false};else if(pts.length===2)planGesture={type:'pinch',startDistance:Math.max(1,planDistance(pts[0],pts[1])),startZoom:state.floorPlanZoom||1,startPan:{...state.floorPlanPan},startCenter:{x:(pts[0].x+pts[1].x)/2,y:(pts[0].y+pts[1].y)/2},moved:true};});floorSvg?.addEventListener('pointermove',e=>{if(!planPointers.has(e.pointerId)||!planGesture)return;planPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const pts=[...planPointers.values()];if(pts.length>=2&&planGesture.type==='pinch'){const rect=floorSvg.getBoundingClientRect(),distance=planDistance(pts[0],pts[1]),center={x:(pts[0].x+pts[1].x)/2,y:(pts[0].y+pts[1].y)/2};state.floorPlanZoom=Math.max(.8,Math.min(2.5,planGesture.startZoom*distance/planGesture.startDistance));state.floorPlanPan={x:planGesture.startPan.x-(center.x-planGesture.startCenter.x)*1200/Math.max(1,rect.width),y:planGesture.startPan.y-(center.y-planGesture.startCenter.y)*650/Math.max(1,rect.height)};planDragClick=true;renderFloorPlan();return}if(pts.length===1&&planGesture.type==='pan'&&(state.floorPlanZoom||1)>1.01){const dx=e.clientX-planGesture.startX,dy=e.clientY-planGesture.startY;if(Math.hypot(dx,dy)>4){planGesture.moved=true;planDragClick=true;floorSvg.classList.add('is-panning');const rect=floorSvg.getBoundingClientRect();state.floorPlanPan={x:planGesture.startPan.x-dx*1200/Math.max(1,rect.width),y:planGesture.startPan.y-dy*650/Math.max(1,rect.height)};renderFloorPlan()}}});const endPlanGesture=e=>{planPointers.delete(e.pointerId);if(!planPointers.size){planGesture=null;floorSvg?.classList.remove('is-panning');setTimeout(()=>{planDragClick=false},0)}else if(planPointers.size===1){const remaining=[...planPointers.entries()][0];planGesture={type:'pan',id:remaining[0],startX:remaining[1].x,startY:remaining[1].y,startPan:{...state.floorPlanPan},moved:true}}};floorSvg?.addEventListener('pointerup',endPlanGesture);floorSvg?.addEventListener('pointercancel',endPlanGesture);floorSvg?.addEventListener('click',e=>{if(planDragClick){e.preventDefault();e.stopImmediatePropagation();planDragClick=false}},true);floorSvg?.addEventListener('dblclick',()=>{state.floorPlanZoom=1;state.floorPlanPan={x:0,y:0};renderFloorPlan()});floorSvg?.addEventListener('wheel',e=>{e.preventDefault();state.floorPlanZoom=Math.max(.8,Math.min(2.5,(state.floorPlanZoom||1)*(e.deltaY<0?1.12:1/1.12)));renderFloorPlan()},{passive:false});
document.querySelectorAll('.tab[data-view]').forEach(b=>{b.onclick=()=>hmNavigate('/'+b.dataset.view)});window.addEventListener('popstate',()=>{const parts=location.pathname.split('/').filter(Boolean);if(parts[0]==='devices'){state.selectedDeviceId=parts[1]||null;state.deviceFilter=new URLSearchParams(location.search).get('status')==='attention'?'attention':'all';renderDevicesPage()}});applyInitialRoute();renderHome();loadAll(true);
